ENGINE=r'''
function mean(x){return x.reduce((a,b)=>a+b,0)/x.length}
function std(x){let m=mean(x);return Math.sqrt(mean(x.map(v=>(v-m)**2)))}
function norm(x){let m=mean(x),s=std(x)+1e-8;return x.map(v=>(v-m)/s)}
function onset(x){return x.map((v,i)=>i?Math.max(0,v-x[i-1]):0)}
function corr(x,y){x=norm(x);y=norm(y);return mean(x.map((v,i)=>v*y[i]))}
function shifted(x,k){return x.map((_,i)=>i-k>=0&&i-k<x.length?x[i-k]:0)}
function features(s){let v=norm(s.visual),a=norm(s.audio),vo=norm(s.visual_onset),ao=norm(s.audio_onset),out=[];
for(let lag=-6;lag<=6;lag++){let x=lag>=0?v.slice(0,v.length-lag):v.slice(-lag),y=lag>=0?a.slice(lag):a.slice(0,a.length+lag),u=lag>=0?vo.slice(0,vo.length-lag):vo.slice(-lag),w=lag>=0?ao.slice(lag):ao.slice(0,ao.length+lag),cs=[],os=[];
let base=Math.floor(x.length/4),extra=x.length%4,idx=0;for(let j=0;j<4;j++){let n=base+(j<extra?1:0);cs.push(corr(x.slice(idx,idx+n),y.slice(idx,idx+n)));os.push(corr(u.slice(idx,idx+n),w.slice(idx,idx+n)));idx+=n}
out.push([corr(x,y),corr(u,w),mean(x.map((z,i)=>Math.abs(z-y[i]))),mean(u.map((z,i)=>Math.abs(z-w[i]))),Math.min(...cs),std(cs),Math.max(...cs),Math.min(...os),std(os),mean(x.map((z,i)=>z*y[i]*u[i]*w[i])),mean(u.map((z,i)=>Math.min(Math.max(z,0),Math.max(w[i],0)))),mean(u.map((z,i)=>Math.max(z,0)*Math.max(w[i],0)))]);
}return out}
function modelPredict(X,m){let p=m.parameters;let logits=X.map(row=>{let z=row.map((x,i)=>(x-p.mean[i])/p.scale[i]);let h=p.b1.map((b,j)=>Math.tanh(b+z.reduce((sum,x,i)=>sum+x*p.w1[i][j],0)));return (h.reduce((sum,x,j)=>sum+x*p.w2[j][0],0)+p.b2[0])/m.temperature});let mx=Math.max(...logits),e=logits.map(x=>Math.exp(x-mx)),total=e.reduce((a,b)=>a+b,0);return e.map(x=>x/total)}
function validateReport(r){let s=r.signals;for(let k of ['visual','audio','global'])if(!Array.isArray(s?.[k])||s[k].length<24||s[k].length>600||s[k].some(x=>!Number.isFinite(x)))throw Error('不合法的信号');if(s.visual.length!==s.audio.length||s.global.length!==s.visual.length)throw Error('信号长度不一致');return s}
function importSafety(result,isImported){return isImported?{...result,accept:false,requires_human_review:true,decision:'review'}:result}
function assessSignals(s,m){let p=modelPredict(features(s),m),idx=p.indexOf(Math.max(...p)),set=p.map((v,i)=>v>=1-m.conformal_q-1e-12?i-6:null).filter(v=>v!==null),energy=Math.min(std(s.visual_onset),std(s.audio_onset)),windows=[];
for(let i=0;i+32<=s.visual.length;i+=16){let sub=Object.fromEntries(Object.entries(s).map(([k,v])=>[k,v.slice(i,i+32)])),q=modelPredict(features(sub),m);windows.push({start:i/20,end:(i+32)/20,lag:q.indexOf(Math.max(...q))-6,confidence:Math.max(...q),energy:Math.min(std(sub.visual_onset),std(sub.audio_onset))})}
let local=windows.filter(x=>x.energy>.008&&x.confidence>=.9).map(x=>x.lag),disagree=local.length>=2&&Math.max(...local)-Math.min(...local)>=2;
return {probabilities:p,lag:idx-6,confidence:p[idx],set,energy,windows,disagree,accept:energy>.008&&p[idx]>=.9&&set.length===1&&!disagree}}
'''

